input.content:
import { toggleNotifications, getNotificationPreference } from "./actions";

export default async function Home() {
  const preference = await getNotificationPreference();

  return (
    <main>
      <h1>Settings</h1>
      <form action={toggleNotifications}>
        <p>Notifications: {preference.enabled ? "On" : "Off"}</p>
        <button type="submit">
          Turn {preference.enabled ? "Off" : "On"}
        </button>
      </form>
    </main>
  );
}

"use server";

import { revalidatePath } from "next/cache";

let notificationsEnabled = false;

export async function toggleNotifications() {
  notificationsEnabled = !notificationsEnabled;
  revalidatePath("/");
  return { enabled: notificationsEnabled };
}

export async function getNotificationPreference() {
  return { enabled: notificationsEnabled };
}

